/** The documented turnaround of each modality — GET /api/v1/imaging/turnaround-targets (who may call: holders of imaging.order.update or diagnostics.quality.view or diagnostics.setup.manage). */
export function listTargets(): Promise<TurnaroundTargetOut[]> {
  return api<TurnaroundTargetOut[]>("GET", `/imaging/turnaround-targets`, undefined);
}

/** Set a modality's turnaround — PUT /api/v1/imaging/turnaround-targets/{modality} (who may call: holders of diagnostics.setup.manage). */
export function setTarget(modality: "XRay" | "MRI" | "CT" | "Ultrasound" | "Doppler" | "Mammography" | "Fluoroscopy" | "Other", body: TargetIn): Promise<TurnaroundTargetOut> {
  return api<TurnaroundTargetOut>("PUT", `/imaging/turnaround-targets/${modality}`, body);
}

/** The critical imaging findings list — GET /api/v1/critical-imaging-findings (who may call: holders of imaging.report.enter or diagnostics.setup.manage or diagnostics.critical.view). */
export function listFindings(query?: { active_only?: boolean }): Promise<CriticalFindingOut[]> {
  return api<CriticalFindingOut[]>("GET", withQuery(`/critical-imaging-findings`, query), undefined);
}

/** Add a critical imaging finding — POST /api/v1/critical-imaging-findings (who may call: holders of diagnostics.setup.manage). */
export function addFinding(body: FindingIn): Promise<CriticalFindingOut> {
  return api<CriticalFindingOut>("POST", `/critical-imaging-findings`, body, { idempotent: true });
}

/** Change or retire a critical imaging finding — PATCH /api/v1/critical-imaging-findings/{finding_id} (who may call: holders of diagnostics.setup.manage). */
export function updateFinding(finding_id: number, body: FindingUpdateIn): Promise<CriticalFindingOut> {
  return api<CriticalFindingOut>("PATCH", `/critical-imaging-findings/${finding_id}`, body);
}

/** The imaging policy and quality assurance plan (PDF) — GET /api/v1/diagnostics/imaging-policy/pdf (who may call: holders of diagnostics.quality.view or imaging.order.update). */
export function imagingPolicy(): Promise<unknown> {
  return api<unknown>("GET", `/diagnostics/imaging-policy/pdf`, undefined);
}
